import math,itertools
sig=lambda z:1/(1+math.exp(-z))
p={}
for h,v,c,r,y in itertools.product((0,1),repeat=5):
 phv=1/6 if h==v else 1/3
 pr=sig(.75*h+.5*c)
 py=sig(-.5+2.5*v+1.75*c)
 p[h,v,c,r,y]=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def cond_y(**conditions):
 idx={'h':0,'v':1,'c':2,'r':3}
 den=sum(val for state,val in p.items() if all(state[idx[k]]==v for k,v in conditions.items()))
 num=sum(val for state,val in p.items() if state[4]==1 and all(state[idx[k]]==v for k,v in conditions.items()))
 return num/den
for h in (0,1):print(f'P(Y=1|H={h})={cond_y(h=h):.6f}')
for c in (0,1):
 for r in (0,1):print(f'P(Y=1|C={c},R={r})={cond_y(c=c,r=r):.6f}')
print('Bayes accuracy using V,C:',sum(max(sig(-.5+2.5*v+1.75*c),1-sig(-.5+2.5*v+1.75*c)) for v,c in itertools.product((0,1),repeat=2))/4)
print('Bird split total:',2849+520+529,'reported:',3538)
print('74.55% times 50:',.7455*50)
PY"
